# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İÇ SALGI BEZLERİ VE SALGILADIKLARI HORMONLAR (FB.6.3.7)</text>\n  <rect x="18" y="46" width="212" height="196" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="124" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Hipofiz ve Tiroit Bezi</text>\n  <text x="30" y="92" font-size="11" font-weight="bold" fill="#1e40af">• Hipofiz Bezi (Beyin altı):</text>\n  <text x="30" y="108" font-size="10.5" fill="#334155">  Büyüme hormonu salgılar; diğer iç</text>\n  <text x="30" y="123" font-size="10.5" fill="#334155">  salgı bezlerini denetler ve yönetir.</text>\n  <text x="30" y="143" font-size="10.5" fill="#1d4ed8">  (Az: Cücelik · Çok: Devlik)</text>\n  <text x="30" y="166" font-size="11" font-weight="bold" fill="#1e40af">• Tiroit Bezi (Soluk borusu önü):</text>\n  <text x="30" y="182" font-size="10.5" fill="#334155">  Tiroksin hormonu salgılar; büyüme</text>\n  <text x="30" y="197" font-size="10.5" fill="#334155">  ve metabolizma hızını düzenler.</text>\n  <text x="30" y="217" font-size="10.5" fill="#1d4ed8">  (İyot eksikliği ➔ Guatr hastalığı)</text>\n\n  <rect x="244" y="46" width="212" height="196" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Böbrek Üstü ve Pankreas</text>\n  <text x="256" y="92" font-size="11" font-weight="bold" fill="#166534">• Böbrek Üstü Bezi:</text>\n  <text x="256" y="108" font-size="10.5" fill="#334155">  Adrenalin salgılar; korku, heyecan,</text>\n  <text x="256" y="123" font-size="10.5" fill="#334155">  öfke anında kalp ve solunumu hızlandırır.</text>\n  <text x="256" y="148" font-size="11" font-weight="bold" fill="#166534">• Pankreas (Karma Bez):</text>\n  <text x="256" y="164" font-size="10.5" fill="#334155">  • İnsülin: Yüksek kan şekerini</text>\n  <text x="256" y="179" font-size="10.5" fill="#334155">    normal seviyeye düşürür.</text>\n  <text x="256" y="196" font-size="10.5" fill="#334155">  • Glukagon: Düşük kan şekerini</text>\n  <text x="256" y="211" font-size="10.5" fill="#334155">    normal seviyeye yükseltir.</text>\n  <text x="256" y="228" font-size="10.5" font-weight="bold" fill="#15803d">  (İnsülin eksikliği ➔ Diyabet)</text>\n\n  <rect x="470" y="46" width="212" height="196" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="576" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Eşeysel Bezler</text>\n  <text x="482" y="92" font-size="11" font-weight="bold" fill="#854d0e">• Yumurtalık (Dişi eşey bezi):</text>\n  <text x="482" y="108" font-size="10.5" fill="#334155">  Östrojen (ve progesteron) salgılar.</text>\n  <text x="482" y="123" font-size="10.5" fill="#334155">  Yumurta üretimi ve dişiye özgü</text>\n  <text x="482" y="138" font-size="10.5" fill="#334155">  ergenlik özelliklerini oluşturur.</text>\n  <text x="482" y="164" font-size="11" font-weight="bold" fill="#854d0e">• Testis (Erkek eşey bezi):</text>\n  <text x="482" y="180" font-size="10.5" fill="#334155">  Testosteron hormonu salgılar.</text>\n  <text x="482" y="195" font-size="10.5" fill="#334155">  Sperm üretimi, ses kalınlaşması ve</text>\n  <text x="482" y="210" font-size="10.5" fill="#334155">  sakal-bıyık çıkışını sağlar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇOCUKLUKTAN ERGENLİĞE GEÇİŞ: BEDENSEL DEĞİŞİMLER (FB.6.3.8)</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">Kızlara Özgü Değişimler</text>\n  <text x="34" y="100" font-size="11.5" fill="#831843">• Yumurtalıklarda yumurta</text>\n  <text x="34" y="118" font-size="11.5" fill="#831843">  hücresi oluşmaya başlar.</text>\n  <text x="34" y="144" font-size="11.5" fill="#831843">• Göğüsler ve kalçalar</text>\n  <text x="34" y="162" font-size="11.5" fill="#831843">  belirginleşir.</text>\n  <text x="34" y="188" font-size="11.5" fill="#831843">• Adet (regl) döngüsü başlar.</text>\n  <text x="125" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Östrojen Hormonu Etkisi</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Ortak Bedensel Değişimler</text>\n  <text x="259" y="98" font-size="11.5" fill="#14532d">• Boy uzaması ve kütle (kilo)</text>\n  <text x="259" y="116" font-size="11.5" fill="#14532d">  artışı hızlanır.</text>\n  <text x="259" y="140" font-size="11.5" fill="#14532d">• Deride yağlanma ve sivilce</text>\n  <text x="259" y="158" font-size="11.5" fill="#14532d">  (akne) oluşumu görülür.</text>\n  <text x="259" y="182" font-size="11.5" fill="#14532d">• Ter salgısı artar; koltuk altı</text>\n  <text x="259" y="200" font-size="11.5" fill="#14532d">  ve özel bölgede kıllanma olur.</text>\n  <text x="350" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Kız ve Erkeklerde Ortak</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Erkeklere Özgü Değişimler</text>\n  <text x="484" y="100" font-size="11.5" fill="#1e3a8a">• Testislerde sperm hücresi</text>\n  <text x="484" y="118" font-size="11.5" fill="#1e3a8a">  üretilmeye başlar.</text>\n  <text x="484" y="144" font-size="11.5" fill="#1e3a8a">• Ses kalınlaşır, gırtlak</text>\n  <text x="484" y="162" font-size="11.5" fill="#1e3a8a">  çıkıntısı belirginleşir.</text>\n  <text x="484" y="188" font-size="11.5" fill="#1e3a8a">• Sakal ve bıyık çıkar, omuzlar</text>\n  <text x="484" y="206" font-size="11.5" fill="#1e3a8a">  genişler ve kaslar gelişir.</text>\n  <text x="575" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Testosteron Hormonu Etkisi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ERGENLİKTE RUHSAL DEĞİŞİMLER VE SİSTEMLERİN SAĞLIĞI</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Ruhsal ve Duygusal Değişimler</text>\n  <text x="40" y="98" font-size="11.5" fill="#581c87">• Kimlik arayışı: «Ben kimim, toplumdaki</text>\n  <text x="40" y="116" font-size="11.5" fill="#581c87">  rolüm nedir?» sorularını sorma</text>\n  <text x="40" y="138" font-size="11.5" fill="#581c87">• Duygusal dalgalanmalar: Aynı gün içinde</text>\n  <text x="40" y="156" font-size="11.5" fill="#581c87">  sevinç, öfke, üzüntü ve alınganlık yaşama</text>\n  <text x="40" y="178" font-size="11.5" fill="#581c87">• Bağımsızlık isteği: Kendi kararlarını alma,</text>\n  <text x="40" y="196" font-size="11.5" fill="#581c87">  yalnız kalma isteği ve arkadaş grubuna önem</text>\n  <text x="182" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Zihinsel: Soyut Düşünme Yeteneği Gelişir</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Sağlıklı Ergenlik ve Sistem Sağlığı</text>\n  <text x="375" y="98" font-size="11.5" fill="#155e75">• Aile bireyleri, öğretmenler ve okul rehberlik</text>\n  <text x="375" y="116" font-size="11.5" fill="#155e75">  servisiyle açık iletişim kurulmalıdır.</text>\n  <text x="375" y="138" font-size="11.5" fill="#155e75">• Spor, sanat, müzik ve kitap okuma gibi</text>\n  <text x="375" y="156" font-size="11.5" fill="#155e75">  faydalı sosyal hobiler edinilmelidir.</text>\n  <text x="375" y="178" font-size="11.5" fill="#155e75">• Yeterli-dengeli beslenilmeli, düzenli uyunmalı,</text>\n  <text x="375" y="196" font-size="11.5" fill="#155e75">  stresten ve zararlı alışkanlıklardan kaçınılmalıdır.</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Doktor Kontrolü Dışında İlaç Kullanılmaz!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
